// Turn raw follower pages into one item per user.
const seen = new Set();
const out = [];

const walk = (v) => {
  if (!v || typeof v !== 'object') return;
  if (Array.isArray(v)) return v.forEach(walk);
  const u = v.user_results && v.user_results.result;
  if (u && u.rest_id && !seen.has(u.rest_id)) {
    seen.add(u.rest_id);
    const l = u.legacy || {};
    const c = u.core || {};
    out.push({
      id: u.rest_id,
      username: c.screen_name || l.screen_name || '',
      name: c.name || l.name || '',
      followers: l.followers_count,
      following: l.friends_count,
      tweets: l.statuses_count,
      verified: !!u.is_blue_verified,
      bio: l.description || '',
      createdAt: c.created_at || l.created_at || '',
    });
  }
  Object.values(v).forEach(walk);
};

for (const item of $input.all()) walk(item.json);
return out.map((json) => ({ json }));
